17	function validatePartialResponseContentLength (headers, range, statusCode, retryCount) {
18	  const contentLength = headers['content-length']
19	  if (contentLength == null) {
20	    return
21	  }
22	
23	  if (!Number.isFinite(range.start) || !Number.isFinite(range.end)) {
24	    return
25	  }
