37	// A stable controller handed to the downstream handler for the lifetime of the
38	// request. Each transparent retry/resume is a *separate* dispatch with its
39	// *own* connection controller. Without a stable proxy the downstream body keeps
40	// flow-controlling the original (now-dead) controller while data flows on the
41	// new one: backpressure pauses the new connection's controller, but the
42	// consumer's resume() targets the old one, so the resumed body stalls forever.
43	// The proxy always forwards to the controller of the currently active connection.
44	// An abort is additionally reported to the handler so it can cancel a pending
45	// retry backoff instead of letting the request hang until the backoff elapses.
46	// The notification is a private callback the handler hands over on construction,
47	// so nothing outside the handler can trigger it.
48	class RetryController {
49	  #onAbort
50	  #paused = false
51	  #target = null
52	
53	  constructor (onAbort) {
54	    this.#onAbort = onAbort
55	  }
56	
57	  set target (target) {
58	    this.#target = target
59	    if (this.#paused) {
60	      target?.pause()
61	    }
62	  }
63	
64	  get target () { return this.#target }
65	
66	  pause () {
67	    this.#paused = true
68	    this.#target?.pause()
69	  }
70	
71	  resume () {
72	    this.#paused = false
73	    this.#target?.resume()
74	  }
75	
76	  abort (reason) {
77	    this.#target?.abort(reason)
78	    this.#onAbort(reason)
79	  }
80	
81	  get paused () { return this.#paused || (this.#target?.paused ?? false) }
82	  get aborted () { return this.#target?.aborted ?? false }
83	  get reason () { return this.#target?.reason ?? null }
84	  get rawHeaders () { return this.#target?.rawHeaders ?? null }
85	  set rawHeaders (value) {
86	    if (this.#target) {
87	      this.#target.rawHeaders = value
88	    }
89	  }
90	
91	  get rawTrailers () { return this.#target?.rawTrailers ?? null }
92	  set rawTrailers (value) {
93	    if (this.#target) {
94	      this.#target.rawTrailers = value
95	    }
96	  }
97	}
