104	      retry: retryFn,
105	      maxRetries,
106	      maxTimeout,
107	      minTimeout,
108	      timeoutFactor,
109	      // Response scoped
110	      methods,
111	      errorCodes,
112	      retryAfter,
113	      statusCodes,
114	      throwOnError
