118	    this.dispatch = dispatch
119	    this.handler = handler
120	    this.opts = { ...dispatchOpts, body: wrapRequestBody(opts.body) }
121	    this.retryOpts = {
122	      throwOnError: throwOnError ?? true,
123	      retry: retryFn ?? RetryHandler[kRetryHandlerDefaultRetry],
124	      retryAfter: retryAfter ?? true,
125	      maxTimeout: maxTimeout ?? 30 * 1000, // 30s,
126	      minTimeout: minTimeout ?? 500, // .5s
127	      timeoutFactor: timeoutFactor ?? 2,
128	      maxRetries: maxRetries ?? 5,
129	      // What errors we should retry
130	      methods: methods ?? ['GET', 'HEAD', 'OPTIONS', 'PUT', 'DELETE', 'TRACE', 'QUERY'],
131	      // Indicates which errors to retry
132	      statusCodes: statusCodes ?? [500, 502, 503, 504, 429],
133	      // List of errors to retry
134	      errorCodes: errorCodes ?? [
135	        'ECONNRESET',
136	        'ECONNREFUSED',
137	        'ENOTFOUND',
138	        'ENETDOWN',
139	        'ENETUNREACH',
140	        'EHOSTDOWN',
141	        'EHOSTUNREACH',
142	        'EPIPE',
143	        'UND_ERR_SOCKET'
144	      ]
145	    }
146	
147	    this.retryCount = 0
148	    this.retryCountCheckpoint = 0
149	    this.headersSent = false
150	    this.start = 0
151	    this.end = null
152	    this.etag = null
153	    this.statusCode = null
154	    this.headers = null
155	    this.controllerProxy = new RetryController(reason => this.#onAbort(reason))
156	    // A retry decision is in flight (the policy may be holding a backoff
157	    // timer). While pending, a consumer abort cancels the wait.
158	    this.retryPending = false
159	    // Backoff timer returned by the retry policy, so #onAbort can cancel it.
160	    // Null for custom policies that do not return their timer.
161	    this.retryTimer = null
162	    // Set once an abort during the backoff delivered the terminal error
163	    // downstream; late policy callbacks and connection errors are then moot.
164	    this.aborted = false
165	  }
