167	  onResponseStartWithRetry (controller, statusCode, headers, statusMessage, err) {
168	    if (this.retryOpts.throwOnError) {
169	      // Preserve old behavior for status codes that are not eligible for retry
170	      if (this.retryOpts.statusCodes.includes(statusCode) === false) {
171	        if (this.headersSent) {
