173	          // earlier attempt. Forwarding this response would replace the
174	          // downstream body and leave the original body pending forever.
175	          this.handler.onResponseError?.(this.controllerProxy, err)
176	        } else {
177	          this.headersSent = true
178	          this.checkpointResponseEnd(headers)
179	          this.handler.onResponseStart?.(this.controllerProxy, statusCode, headers, statusMessage)
180	        }
181	      } else {
182	        this.error = err
183	      }
184	
185	      return
186	    }
