188	    if (isDisturbed(this.opts.body)) {
189	      this.headersSent = true
190	      this.checkpointResponseEnd(headers)
191	      this.handler.onResponseStart?.(this.controllerProxy, statusCode, headers, statusMessage)
192	      return
193	    }
194	
195	    function shouldRetry (passedErr) {
196	      if (this.aborted) {
197	        // Aborted while the policy was deciding; the decision is moot.
198	        return
199	      }
200	      this.retryPending = false
201	      this.retryTimer = null
202	
203	      if (passedErr) {
204	        if (this.headersSent) {
205	          // The downstream handler already received the response from an
206	          // earlier attempt. Forwarding this response would replace the
207	          // downstream body and leave the original body pending forever.
208	          this.handler.onResponseError?.(this.controllerProxy, passedErr)
209	        } else {
210	          this.headersSent = true
211	          this.checkpointResponseEnd(headers)
212	          this.handler.onResponseStart?.(this.controllerProxy, statusCode, headers, statusMessage)
213	        }
214	        controller.resume()
215	        return
216	      }
217	
218	      this.error = err
219	      controller.resume()
220	    }
221	
222	    // The pause()/resume() pair (here and in shouldRetry) acts on THIS
223	    // connection's controller -- never the downstream proxy. We hold this exact
224	    // connection while the retry policy decides (possibly after a timeout) and
225	    // must resume the same one. Routing this through controllerProxy would risk
226	    // resuming a different connection if a later dispatch re-points the proxy in
227	    // between, leaving this one paused forever -- the very stall the proxy exists
228	    // to prevent.
229	    controller.pause()
230	    // The default policy returns its backoff timer so an abort can cancel it;
231	    // a custom policy may return anything (or nothing), which is ignored.
232	    this.retryPending = true
233	    this.retryTimer = this.retryOpts.retry(
234	      err,
235	      {
