259	    // same instance to every later callback of the dispatch. onRequestStart is
260	    // the first callback (it is where the controller is created), so re-pointing
261	    // the proxy here is enough to keep it on the active connection across every
262	    // transparent retry/resume.
263	    this.controllerProxy.target = controller
