281	  static [kRetryHandlerDefaultRetry] (err, { state, opts }, cb) {
282	    const { statusCode, code, headers } = err
283	    const { method, retryOptions } = opts
284	    const {
285	      maxRetries,
286	      minTimeout,
287	      maxTimeout,
288	      timeoutFactor,
289	      statusCodes,
290	      errorCodes,
291	      methods,
292	      retryAfter
293	    } = retryOptions
294	    const { counter } = state
295	
296	    // Any code that is not a Undici's originated and allowed to retry
297	    if (code && code !== 'UND_ERR_REQ_RETRY' && !errorCodes.includes(code)) {
298	      cb(err)
299	      return
300	    }
301	
302	    // If a set of method are provided and the current method is not in the list
303	    if (Array.isArray(methods) && !methods.includes(method)) {
304	      cb(err)
305	      return
306	    }
307	
308	    // If a set of status code are provided and the current status code is not in the list
309	    if (
310	      statusCode != null &&
311	      Array.isArray(statusCodes) &&
312	      !statusCodes.includes(statusCode)
313	    ) {
314	      cb(err)
315	      return
316	    }
317	
318	    // If we reached the max number of retries
319	    if (counter > maxRetries) {
320	      cb(err)
321	      return
322	    }
323	
324	    let retryAfterHeader = retryAfter === false ? undefined : headers?.['retry-after']
325	    if (retryAfterHeader) {
326	      retryAfterHeader = Number(retryAfterHeader)
327	      retryAfterHeader = Number.isNaN(retryAfterHeader)
328	        ? calculateRetryAfterHeader(headers['retry-after'])
329	        : retryAfterHeader * 1e3 // Retry-After is in seconds
330	    }
331	
332	    const retryTimeout =
333	      retryAfterHeader === 0
334	        ? 0
335	        : retryAfterHeader > 0
336	          ? Math.min(retryAfterHeader, maxTimeout)
337	          : Math.min(minTimeout * timeoutFactor ** (counter - 1), maxTimeout)
338	
339	    // Return the backoff timer so the handler can cancel it when the
340	    // consumer aborts while the retry decision is pending.
341	    return setTimeout(() => cb(null), retryTimeout)
342	  }
