344	  onResponseStart (controller, statusCode, headers, statusMessage) {
345	    if (statusCode < 200) {
346	      this.handler.onResponseStart?.(this.controllerProxy, statusCode, headers, statusMessage)
347	      return
348	    }
349	
350	    this.error = null
351	    this.retryCount += 1
352	    this.statusCode = statusCode
353	    this.headers = headers
354	
355	    // Checkpoint for resume from where we left it
