373	          headers,
374	          data: { count: this.retryCount }
375	        })
376	      }
377	
378	      // Let's start with a weak etag check
379	      if (this.etag != null && this.etag !== headers.etag) {
380	        // We always throw here as we want to indicate that we entred unexpected path
