387	      validatePartialResponseContentLength(headers, contentRange, statusCode, this.retryCount)
388	
389	      const { start, size, end = size ? size - 1 : null } = contentRange
390	
391	      if (this.start !== start || (this.end != null && this.end !== end)) {
392	        throw new RequestRetryError('Content-Range mismatch', statusCode, {
393	          headers,
394	          data: { count: this.retryCount }
395	        })
396	      }
397	
398	      return
399	    }
