401	    if (statusCode >= 300) {
402	      const err = new RequestRetryError('Request failed', statusCode, {
403	        headers,
404	        data: {
405	          count: this.retryCount
406	        }
407	      })
408	
409	      this.onResponseStartWithRetry(controller, statusCode, headers, statusMessage, err)
410	      return
411	    }
412	
413	    if (this.end == null) {
414	      if (statusCode === 206) {
