464	      ) {
465	        this.etag = null
466	      }
467	
468	      this.headersSent = true
469	      this.handler.onResponseStart?.(
470	        this.controllerProxy,
471	        statusCode,
472	        headers,
473	        statusMessage
474	      )
475	    } else {
476	      throw new RequestRetryError('Request failed', statusCode, {
477	        headers,
478	        data: { count: this.retryCount }
479	      })
480	    }
481	  }
