483	  onResponseData (_controller, chunk) {
484	    if (this.error) {
485	      return
486	    }
487	
488	    this.start += chunk.length
489	
490	    this.handler.onResponseData?.(this.controllerProxy, chunk)
491	  }
492	
493	  onResponseEnd (_controller, trailers) {
494	    if (this.error && this.retryOpts.throwOnError) {
495	      throw this.error
496	    }
497	
498	    if (!this.error) {
499	      // Verify that the received body length matches the expected range
