501	      if (this.end != null && Number.isFinite(this.end)) {
502	        if (this.start !== this.end + 1) {
503	          throw new RequestRetryError('Content-Range mismatch', this.statusCode, {
504	            headers: this.headers,
505	            data: { count: this.retryCount }
506	          })
507	        }
508	      }
509	      this.retryCount = 0
510	      return this.handler.onResponseEnd?.(this.controllerProxy, trailers)
511	    }
512	
513	    this.retry()
514	  }
