520	      // Weak etag check - weak etags will make comparison algorithms never match
521	      if (this.etag != null) {
522	        headers['if-match'] = this.etag
523	      }
524	
525	      this.opts = {
526	        ...this.opts,
527	        headers: {
528	          ...this.opts.headers,
529	          ...headers
530	        }
531	      }
532	    }
533	
534	    try {
535	      this.retryCountCheckpoint = this.retryCount
536	      this.dispatch(this.opts, this)
537	    } catch (err) {
538	      this.handler.onResponseError?.(this.controllerProxy, err)
539	    }
540	  }
