542	  onResponseError (controller, err) {
543	    if (this.aborted) {
544	      // #onAbort already delivered the terminal error downstream; the late
545	      // error of the torn-down connection must not be forwarded twice.
546	      return
547	    }
548	
549	    // controller is THIS failed connection (not the proxy): we inspect whether
550	    // the consumer aborted it to decide retry-vs-propagate.
551	    if (controller?.aborted || isDisturbed(this.opts.body) || (this.headersSent && !this.resume)) {
552	      this.handler.onResponseError?.(this.controllerProxy, err)
553	      return
554	    }
555	
556	    function shouldRetry (returnedErr) {
557	      if (this.aborted) {
558	        // Aborted while the policy was deciding; the decision is moot.
559	        return
560	      }
561	      this.retryPending = false
562	      this.retryTimer = null
563	
564	      if (!returnedErr) {
565	        this.retry()
566	        return
567	      }
568	
569	      this.handler?.onResponseError?.(this.controllerProxy, returnedErr)
570	    }
571	
572	    // We reconcile in case of a mix between network errors
573	    // and server error response
574	    if (this.retryCount - this.retryCountCheckpoint > 0) {
575	      // We count the difference between the last checkpoint and the current retry count
576	      this.retryCount =
577	        this.retryCountCheckpoint +
578	        (this.retryCount - this.retryCountCheckpoint)
579	    } else {
580	      this.retryCount += 1
581	    }
582	
583	    this.retryPending = true
584	    this.retryTimer = this.retryOpts.retry(
585	      err,
586	      {
587	        state: { counter: this.retryCount },
588	        opts: { retryOptions: this.retryOpts, ...this.opts }
589	      },
590	      shouldRetry.bind(this)
591	    ) ?? null
592	  }
593	
594	  #onAbort (reason) {
595	    // A consumer abort lands on the controller proxy. If the retry policy is
596	    // still deciding (typically holding a backoff timer), cancel the wait and
597	    // surface the abort immediately instead of letting the request hang until
598	    // the backoff elapses.
599	    if (!this.retryPending) {
600	      return
601	    }
602	
603	    this.aborted = true
604	    this.retryPending = false
605	    clearTimeout(this.retryTimer)
606	    this.retryTimer = null
607	    this.handler.onResponseError?.(this.controllerProxy, reason ?? new RequestAbortedError())
608	  }
609	}
610	
611	module.exports = RetryHandler
