'use strict'

const { createServer } = require('node:http')
const { once } = require('node:events')
const { Client, interceptors } = require('.')

async function main () {
  let counter = 0
  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    counter += 1
    res.setHeader('Connection', 'close')
    if (counter < 3) {
      res.statusCode = 500
      res.end('error')
    } else {
      res.statusCode = 200
      res.end('hello world')
    }
  })
  server.listen(0)
  await once(server, 'listening')

  const client = new Client(`http://localhost:${server.address().port}`)
    .compose(interceptors.retry({ maxRetries: 3, minTimeout: 50, timeoutFactor: 1, throwOnError: false }))

  const timer = setTimeout(() => {
    console.log('TIMEOUT: request hung. attempts =', counter)
    process.exit(1)
  }, 5000)

  const res = await client.request({ method: 'GET', path: '/' })
  const body = await res.body.text()
  clearTimeout(timer)
  console.log('statusCode', res.statusCode, 'body', JSON.stringify(body), 'attempts', counter)

  await client.close()
  server.close()
}

main().catch((err) => {
  console.error('ERR', err)
  process.exit(1)
})

