'use strict'

const { createServer } = require('node:net')
const { once } = require('node:events')
const { Client, interceptors } = require('.')

async function main () {
  let counter = 0
  const server = createServer((socket) => {
    socket.on('error', () => {})
    socket.on('data', () => {
      counter += 1
      const body = 'server is down'
      socket.write(
        `HTTP/1.1 500 Internal Server Error\r\nConnection: close\r\nContent-Length: ${body.length}\r\n\r\n${body}`
      )
      // Force an RST so the client parser is finished while it is paused.
      setTimeout(() => socket.resetAndDestroy(), 10)
    })
  })
  server.listen(0)
  await once(server, 'listening')

  const client = new Client(`http://localhost:${server.address().port}`)
    .compose(interceptors.retry({ maxRetries: 2, minTimeout: 50, timeoutFactor: 1, throwOnError: false }))

  const timer = setTimeout(() => {
    console.log('TIMEOUT: request hung. attempts =', counter)
    process.exit(1)
  }, 5000)

  const res = await client.request({ method: 'GET', path: '/' })
  const body = await res.body.text()
  clearTimeout(timer)
  console.log('statusCode', res.statusCode, 'body', JSON.stringify(body), 'attempts', counter)

  await client.close()
  server.close()
}

main().catch((err) => {
  console.error('ERR', err)
  process.exit(1)
})

