  // given its onResponseStart.
  #flushRetainedResponse () {
    const body = this.retainedBody
    const trailers = this.retainedTrailers
    const ended = this.retainedEnd
    this.#discardRetainedResponse()

    for (let i = 0; i < body.length; i++) {
      this.start += body[i].length
      this.handler.onResponseData?.(this.controllerProxy, body[i])
    }

    if (ended) {
      this.onResponseEnd(this.controllerProxy, trailers)
    }
  }

  #discardRetainedResponse () {
    this.retainedBody = []
    this.retainedTrailers = null
    this.retainedEnd = false
  }

  #onAbort (reason) {
    // A consumer abort lands on the controller proxy. If the retry policy is
    // still deciding (typically holding a backoff timer), cancel the wait and
    // surface the abort immediately instead of letting the request hang until
    // the backoff elapses.
    if (!this.retryPending) {
      return
    }

    this.aborted = true
    this.retryPending = false
    this.retainingResponse = false
    this.#discardRetainedResponse()
    clearTimeout(this.retryTimer)
    this.retryTimer = null
    this.handler.onResponseError?.(this.controllerProxy, reason ?? new RequestAbortedError())
  }
}

module.exports = RetryHandler

