'use strict'

const { tspl } = require('@matteo.collina/tspl')
const { test, after } = require('node:test')
const { createServer } = require('node:net')
const { once } = require('node:events')

const { Pool, RetryAgent, RetryHandler } = require('..')

// A retryable response can *complete* while the retry handler holds its
// connection paused waiting for the retry policy: when the peer closes the
// connection the parser drains and finishes the message regardless of the
// pause. Those responses must be retained until the policy decides, otherwise
// the attempt is lost (the request hangs) or a body is pushed to a downstream
// handler that never received onResponseStart.

// Responses are written by hand because the shape matters: a body-less
// response with an explicit content-length leaves nothing buffered on the
// socket once the headers are parsed, so the peer's FIN reaches the parser
// while the retry handler holds it paused. Anything still buffered (a body, a
// chunked terminator) would instead keep the connection alive until the retry
// policy resumes it.
function respond (socket, statusLine, body = '') {
  socket.write(
    `HTTP/1.1 ${statusLine}\r\n` +
    'Connection: close\r\n' +
    `Content-Length: ${Buffer.byteLength(body)}\r\n` +
    `\r\n${body}`
  )
  socket.end()
}

// One connection per request: every response closes the connection.
function closingServer (onRequest) {
  return createServer((socket) => {
    socket.on('error', () => {})
    socket.once('data', (data) => {
      onRequest(socket, data.toString().split(' ')[1])
    })
  })
}

test('retries advance when the peer closes the connection on a retryable response', async t => {
  t = tspl(t, { plan: 3 })

  let counter = 0
  const server = closingServer((socket) => {
    if (++counter < 3) {
      respond(socket, '500 Internal Server Error')
      return
    }

    respond(socket, '200 OK', 'hello world')
  })

  server.listen(0)
  await once(server, 'listening')

  const agent = new RetryAgent(new Pool(`http://localhost:${server.address().port}`), {
    throwOnError: false,
    maxRetries: 5,
    minTimeout: 5,
    timeoutFactor: 1
  })

  after(async () => {
    await agent.close()
    server.close()
    await once(server, 'close')
  })

  const res = await agent.request({ method: 'GET', path: '/' })

  t.strictEqual(res.statusCode, 200)
  t.strictEqual(await res.body.text(), 'hello world')
  t.strictEqual(counter, 3)

  await t.completed
})

test('concurrent requests all settle when the peer closes the connection on a retryable response', async t => {
  t = tspl(t, { plan: 13 })

  const concurrency = 4
  const attempts = new Map()
  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    const count = (attempts.get(req.url) ?? 0) + 1
    attempts.set(req.url, count)

    if (count < 3) {
      res.writeHead(500, { connection: 'close' })
      res.end()
      return
    }

    res.writeHead(200, { connection: 'close' })
    res.end(`ok ${req.url}`)
  })

  server.listen(0)
  await once(server, 'listening')

  const agent = new RetryAgent(
    new Pool(`http://localhost:${server.address().port}`, { connections: concurrency }),
    {
      throwOnError: false,
      maxRetries: 5,
      minTimeout: 5,
      timeoutFactor: 1
    }
  )

  after(async () => {
    await agent.close()
    server.close()
    await once(server, 'close')
  })

  const responses = await Promise.all(
    Array.from({ length: concurrency }, (_, i) =>
      agent.request({ method: 'GET', path: `/${i}` })
    )
  )

  for (let i = 0; i < concurrency; i++) {
    t.strictEqual(responses[i].statusCode, 200)
    t.strictEqual(await responses[i].body.text(), `ok /${i}`)
    t.strictEqual(attempts.get(`/${i}`), 3)
  }

  t.strictEqual(attempts.size, concurrency)

  await t.completed
})

test('the final response is preserved when retries are exhausted on a closing connection', async t => {
  t = tspl(t, { plan: 3 })

  let counter = 0
  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    res.writeHead(500, { connection: 'close' })

    if (++counter < 3) {
      res.end()
      return
    }

    res.end('server is down')
  })

  server.listen(0)
  await once(server, 'listening')

  const agent = new RetryAgent(new Pool(`http://localhost:${server.address().port}`), {
    throwOnError: false,
    maxRetries: 2,
    minTimeout: 5,
    timeoutFactor: 1
  })

  after(async () => {
    await agent.close()
    server.close()
    await once(server, 'close')
  })

  const res = await agent.request({ method: 'GET', path: '/' })

  t.strictEqual(res.statusCode, 500)
  t.strictEqual(await res.body.text(), 'server is down')
  t.strictEqual(counter, 3)

  await t.completed
})

// The integration tests above can only retain an *empty* body over HTTP/1.1 --
// a body left in the socket buffer keeps the peer's FIN from reaching the
// parser. The two tests below drive the handler directly so the retained body
// path is covered for the transports that can deliver one (e.g. an HTTP/2
// stream closing while paused).

function retainedResponseHandler ({ retry }) {
  const events = []
  const handler = new RetryHandler(
    {
      method: 'GET',
      path: '/',
      retryOptions: {
        throwOnError: false,
        // Hand the decision back to the test instead of arming a backoff timer.
        retry: (err, _state, cb) => {
          retry.settle = (passedErr) => cb(passedErr === undefined ? err : passedErr)
        }
      }
    },
    {
      dispatch: () => events.push('dispatch'),
      handler: {
        onRequestStart () {},
        onResponseStart (_controller, statusCode) { events.push(['start', statusCode]) },
        onResponseData (_controller, chunk) { events.push(['data', chunk.toString()]) },
        onResponseEnd () { events.push('end') },
        onResponseError (_controller, err) { events.push(['error', err.message]) }
      }
    }
  )

  const controller = {
    paused: false,
    pause () { this.paused = true },
    resume () { this.paused = false }
  }

  handler.onRequestStart(controller, {})
  handler.onResponseStart(controller, 500, { 'content-length': '5' }, 'Internal Server Error')

  return { events, handler, controller }
}

test('a response body that arrives while paused is delivered once retries are exhausted', (t) => {
  t = tspl(t, { plan: 3 })

  const retry = {}
  const { events, handler, controller } = retainedResponseHandler({ retry })

  // The connection is paused while the policy decides, but the peer closed it,
  // so the parser pushes the rest of the message through anyway.
  t.strictEqual(controller.paused, true)
  handler.onResponseData(controller, Buffer.from('boom!'))
  handler.onResponseEnd(controller, {})

  // Nothing may reach the downstream handler before it has a response to
  // attach it to.
  t.deepStrictEqual(events, [])

  // Retries exhausted: this is the final response, body included.
  retry.settle()

  t.deepStrictEqual(events, [
    ['start', 500],
    ['data', 'boom!'],
    'end'
  ])
})

test('a response that finishes while paused still triggers the next attempt', (t) => {
  t = tspl(t, { plan: 2 })

  const retry = {}
  const { events, handler } = retainedResponseHandler({ retry })

  handler.onResponseData(Object, Buffer.from('boom!'))
  handler.onResponseEnd(Object, {})

  // The policy decides to retry: the retained response is dropped and the
  // attempt is re-dispatched even though the connection is already gone.
  retry.settle(null)

  t.deepStrictEqual(events, ['dispatch'])
  t.strictEqual(handler.start, 0)
})

